<script setup>
import {ref,computed} from 'vue';
import UiButton from './UiButton.vue';import UiBadge from './UiBadge.vue';import UiDialog from './UiDialog.vue';import RoomArt from './RoomArt.vue';import {getPreview} from '../previewState.js';
const props=defineProps({page:String});const emit=defineEmits(['navigate','create']);const state=getPreview();const prompt=ref('');const conversations=ref([]);const active=ref(null);const query=ref('');const modal=ref('');const draft=ref('');const error=ref('');const selected=ref(null);const blocks=ref(['Image input','Detect objects','Review output']);const workflowName=ref('Room analysis');const provider=ref('Local sample');const eventFilter=ref('All');const message=ref('');
const assets=computed(()=>state.images.filter(i=>i.name.toLowerCase().includes(query.value.toLowerCase())));
function send(){if(!prompt.value.trim())return;const item={id:Date.now(),prompt:prompt.value.trim()};conversations.value.unshift(item);active.value=item;prompt.value='';}
function saveWorkflow(){if(!workflowName.value.trim()){error.value='Enter a workflow name.';return;}state.workflows.push({name:workflowName.value.trim(),blocks:[...blocks.value]});message.value='Workflow draft saved locally.';modal.value='';}
</script>
<template><div class="studio"><div class="studio-preview"><UiBadge tone="purple">Coming soon</UiBadge><span>Local preview. No messages, integrations or jobs are sent.</span></div><div v-if="message" class="notice" role="status">{{message}}</div>
<template v-if="page==='agent'"><div class="agent-layout"><aside class="panel"><h3>Conversations</h3><UiButton @click="active=null">New conversation</UiButton><button v-for="c in conversations" :key="c.id" class="model-choice" @click="active=c">{{c.prompt}}</button><p v-if="!conversations.length">No recent conversations.</p></aside><section class="agent-main"><h2>What would you like to build?</h2><p>Describe your vision project and explore a sample plan.</p><form class="agent-composer" @submit.prevent="send"><textarea v-model="prompt" placeholder="e.g. Detect walls and windows in room photos" aria-label="Project idea" rows="3"/><UiButton type="submit" variant="primary" :disabled="!prompt.trim()">Preview a plan</UiButton></form><div class="studio-actions"><UiButton @click="prompt='Detect walls and windows in room photos'">Wall segmentation</UiButton><UiButton @click="prompt='Count bottles in product photos'">Object counting</UiButton><UiButton @click="emit('create')">Build a model</UiButton></div><article v-if="active" class="panel"><UiBadge>Scripted response preview</UiBadge><h3>{{active.prompt}}</h3><ol><li>Create a project and choose its task and data policy.</li><li>Upload a representative sample collection.</li><li>Label objects, review images and prepare a dataset version.</li><li>Configure a training preview and inspect its results.</li></ol><p>This is a fixed example plan; no AI model was called.</p><UiButton variant="primary" @click="emit('create')">Create project</UiButton><UiButton @click="emit('navigate','workflows')">Explore workflows</UiButton></article><div v-else class="choice-grid"><article class="panel"><RoomArt/><h3>Room understanding</h3><p>Outline walls, windows and doors.</p></article><article class="panel"><RoomArt :variant="1"/><h3>Dataset quality</h3><p>Review annotations before training.</p></article></div></section></div></template>
<template v-else-if="page==='assets'"><div class="studio-actions"><input v-model="query" class="text-input" placeholder="Search assets" aria-label="Search assets"><UiButton @click="emit('navigate','upload')">Add assets</UiButton></div><div class="media-grid"><button v-for="a in assets" :key="a.id" class="media-card" @click="selected=a;modal='Asset details'"><RoomArt v-if="a.sample" :variant="a.variant"/><img v-else :src="a.url" :alt="a.name"><strong>{{a.name}}</strong><UiBadge>{{a.state}}</UiBadge></button></div><div v-if="!assets.length" class="empty-state"><h2>No matching assets</h2><UiButton @click="query=''">Clear search</UiButton></div></template>
<template v-else-if="page==='workflows'"><div class="studio-actions"><p>Connect input, prediction and review steps in a local draft.</p><UiButton variant="primary" @click="modal='Workflow editor';error=''">New workflow</UiButton></div><div class="choice-grid"><article v-for="(w,i) in state.workflows" :key="i" class="panel"><h2>{{w.name}}</h2><UiBadge>Local draft</UiBadge><p>{{(w.blocks||blocks).join(' > ')}}</p><UiButton @click="workflowName=w.name;blocks=[...(w.blocks||blocks)];modal='Workflow editor'">Open as new draft</UiButton></article></div><div v-if="!state.workflows.length" class="empty-state"><h2>Build your first workflow</h2><p>Start with image input, detection and review.</p><UiButton @click="modal='Workflow editor'">Use starter template</UiButton></div></template>
<template v-else-if="page==='events'"><div class="studio-actions"><select v-model="eventFilter" aria-label="Filter events"><option>All</option><option>Review</option><option>Training</option></select><UiButton @click="message='Sample event feed refreshed.'">Refresh</UiButton></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Type</th><th>Status</th></tr></thead><tbody><tr v-if="eventFilter!=='Training'"><td>Room collection awaits review</td><td>Review</td><td>Sample event</td></tr><tr v-if="eventFilter!=='Review'"><td>Dataset ready for a training preview</td><td>Training</td><td>Sample event</td></tr></tbody></table></div></template>
<template v-else><h2>Discover sample datasets</h2><p>Search this local illustrative catalog. No external collection is accessed.</p><input v-model="query" class="text-input" aria-label="Search collections" placeholder="Search collections"><div class="choice-grid"><article v-for="name in ['Indoor rooms','Bottle detection'].filter(n=>n.toLowerCase().includes(query.toLowerCase()))" :key="name" class="panel"><RoomArt/><h3>{{name}}</h3><UiBadge>Synthetic preview</UiBadge><p>Explore the import flow with sample data.</p><UiButton @click="draft=name;modal='Import collection'">View collection</UiButton></article></div></template>
<UiDialog :open="!!modal" :title="modal" @close="modal=''">
<template v-if="modal==='Asset details'"><RoomArt v-if="selected.sample"/><img v-else :src="selected.url" :alt="selected.name" style="max-width:100%"><h3>{{selected.name}}</h3><p>{{selected.state}} / {{selected.tags.join(', ')}}</p><UiButton @click="modal='';emit('navigate','dataset')">Open dataset</UiButton></template>
<template v-else-if="modal==='Workflow editor'"><label class="field-label">Workflow name<input v-model="workflowName" class="text-input"></label><div class="learning-flow"><article v-for="(b,i) in blocks" :key="i"><strong>{{i+1}}. {{b}}</strong><UiButton v-if="i>0" @click="blocks.splice(i,1)">Remove</UiButton></article></div><label class="field-label">Add a block<select v-model="provider"><option>Confidence filter</option><option>Class filter</option><option>Count objects</option><option>Review output</option></select></label><UiButton @click="blocks.push(provider==='Local sample'?'Confidence filter':provider)">Add block</UiButton><p v-if="error" role="alert">{{error}}</p><div class="dialog-actions"><UiButton @click="message='Sample workflow validation passed: input and output are preview-only.'">Validate preview</UiButton><UiButton variant="primary" @click="saveWorkflow">Save local workflow</UiButton></div></template>
<template v-else><h3>{{draft}}</h3><p>Coming soon. The next step uses synthetic images in the upload preview.</p><UiButton @click="modal='';emit('navigate','upload')">Continue to upload preview</UiButton></template>
</UiDialog></div></template>
<style scoped>.agent-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:30px}.agent-main{padding:25px;background:radial-gradient(ellipse at top,var(--aadml-soft),transparent 70%)}.agent-main>h2{font-size:30px;text-align:center}.agent-main>p{text-align:center}.agent-composer{padding:16px;background:white;border:1px solid var(--aadml-outline);border-radius:10px;box-shadow:0 0 0 12px #2563eb55;margin-top:35px}.agent-composer textarea{width:100%;border:0;resize:vertical;font:inherit;padding:10px;outline-color:var(--aadml-focus)}.agent-main .panel>svg{width:100%}.agent-main ol{line-height:2;font-size:13px}.choice-grid .panel>svg{width:100%;max-height:180px}.learning-flow article{display:flex;justify-content:space-between;align-items:center}.dialog svg{max-width:100%}@media(max-width:1000px){.agent-layout{grid-template-columns:1fr}.agent-layout>aside{display:none}.agent-main{padding:10px}}</style>
